-- stage_init 기반 유틸들
farm_util = {}

function farm_util.get_farm_system()
	return CS.Oak.HeavenHoldFarmSystem.Instance
end

function farm_util.get_current_user_data()
	return CS.Oak.UserHeavenHoldFarm.CurrentData
end

function farm_util.get_local_user_data()
	return CS.Oak.UserHeavenHoldFarm.Me
end

function farm_util.is_in_local_farm()
	return CS.Oak.UserHeavenHoldFarm.IsInLocalFarm
end

--- 내 농장이 아니라도 사용할 수 있다.
function farm_util.is_farm_tutorial_finished()
	local hut = get_field_object('farm_hut')
	return hut.FieldObjectBehaviour.BuildingSpec ~= nil
end

--- 내 농장이 아니라도 사용할 수 있다.
function farm_util.get_building_data_with_type(building_type)
	local data = farm_util.get_current_user_data()
	return data:GetFarmBuildingData(building_type)
end

function farm_util.get_deco_spec(building_data)
	local local_spec_id = building_data.LocalSpecId
	return CS.Oak.HeavenHoldFarmSystem.Instance.ResourceManager:GetDecorationSpec(local_spec_id)
end

function farm_util.get_deco_data_key(building_data)
	return farm_util.get_deco_spec(building_data).DataKey
end

function farm_util.play_screenplay(func, ...)
	local args =  {...}
	local routine = function()
		farm_util.start_screenplay()

		yield_return_func(func, table.unpack(args))

		farm_util.end_screenplay()
	end

	return start_coroutine(routine)
end

function farm_util.start_screenplay()
	character_util.reset_action_state(user_party.Leader)
	field_ui_manager:Hide()
	farm_util.hide_concealable_presets()
	party_util.stop_and_disable_control()
end

function farm_util.end_screenplay()
	party_util.reset_controllers()
	farm_util.show_concealable_presets()
	field_ui_manager:Show()
end

function farm_util.play_ambient_sound(requester, sound_key, pos_or_parent)
	CS.Oak.HeavenHoldFarmSystem.Instance.SoundManager:PlayAmbientSound(requester, sound_key, pos_or_parent)
end

function farm_util.stop_ambient_sound(requester)
	CS.Oak.HeavenHoldFarmSystem.Instance.SoundManager:StopAmbientSound(requester)
end

function farm_util.set_deco_data(building_id, sub_key, value)
	CS.Oak.HeavenHoldFarmSystem.Instance.DataManager:SetData(building_id, sub_key, value)
end

function farm_util.get_deco_data(building_id, sub_key)
	return CS.Oak.HeavenHoldFarmSystem.Instance.DataManager:GetData(building_id, sub_key)
end

function farm_util.remove_relative_deco_datas(building_id)
	return CS.Oak.HeavenHoldFarmSystem.Instance.DataManager:RemoveRelativeDatas(building_id)
end

function farm_util.show_concealable_presets()
	return CS.Oak.HeavenHoldFarmSystem.Instance.ResourceManager:ShowConcealablePresets()
end

function farm_util.hide_concealable_presets()
	return CS.Oak.HeavenHoldFarmSystem.Instance.ResourceManager:HideConcealablePresets()
end

function farm_util.is_sfx_playing(sound_key)
	return CS.Oak.HeavenHoldFarmSystem.Instance.SoundManager:IsSfxPlaying(sound_key)
end

return {
	create = function()
		return farm_util
	end
}

