metatable_helper = {}

---@generic T, B
---@param table T
---@param base B
---@return B | T
function metatable_helper.inherit(table, base)
	return setmetatable(table, {
		__index = base
	})
end

---@class LuaFxLoaderBase
local fx_loader_base = {
	---@param this self
	create_all = function(this)
		for _, creator in pairs(this) do
			creator()
		end
	end,
	---@param this self
	load_async = function(this)
		this:create_all()

		yield_return_func(unity_object_pool.WaitAll)
	end
}

local fx_loader_meta = {
	__index = fx_loader_base
}

---@generic V
---@param getters V
---@return V | LuaFxLoaderBase
function metatable_helper.create_fx_accessor(getters)
	return setmetatable(getters, fx_loader_meta)
end

return {
	create = function()
		return metatable_helper
	end
}
